{"security_risk":"MEDIUM","summary":"Compute compliance metrics and write q01-q05 JSON outputs","command":"python3 - <<'PY'
import os, json, math
from collections import OrderedDict
import pandas as pd

DATA_DIR='/app/data'
OUT_DIR='/app/output'
os.makedirs(OUT_DIR, exist_ok=True)

mes=pd.read_csv(os.path.join(DATA_DIR,'mes_log.csv'), dtype={'run_id':str,'board_family':str,'board_id':str})
